package com.mineserve.mobile.ui

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.asImageBitmap
import com.mineserve.mobile.data.ServerCore
import java.util.EnumMap

internal object OfficialCoreLogos {
    private val cache = EnumMap<ServerCore, ImageBitmap>(ServerCore::class.java)

    fun bitmapFor(core: ServerCore): ImageBitmap? {
        synchronized(cache) {
            cache[core]?.let { return it }
            val b64 = base64For(core) ?: return null
            val bytes = runCatching { Base64.decode(b64, Base64.DEFAULT) }.getOrNull() ?: return null
            val bmp = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap() ?: return null
            cache[core] = bmp
            return bmp
        }
    }

    private fun base64For(core: ServerCore): String? = when (core) {
        ServerCore.Fabric -> ""
        ServerCore.Paper -> ""
        ServerCore.NeoForge -> ""
        ServerCore.Forge -> ""
        ServerCore.Purpur -> ""
        ServerCore.PowerNukkitX -> ""
        ServerCore.Spigot -> ""
        ServerCore.Quilt -> ""
        ServerCore.Leaves -> ""
        ServerCore.Leaf -> ""
        ServerCore.Velocity -> ""
        ServerCore.PocketMine -> ""
        ServerCore.Allay -> ""
        ServerCore.Vanilla -> ""
        ServerCore.CraftBukkit -> ""
        ServerCore.BungeeCord -> ""
        ServerCore.Unknown -> null
    }
}
